func (this *Mercado) fetchMarketsBody(ch chan AsyncResult[[]MarketInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	listEp344 := <-this.PublicGetCoins(params)
	if listEp344.Err != nil {
		panic(listEp344.Err)
	}
	var response []any = listEp344.Value
	//
	//     [
	//         "BCH",
	//         "BTC",
	//         "ETH",
	//         "LTC",
	//         "XRP",
	//         "MBPRK01",
	//         "MBPRK02",
	//         "MBPRK03",
	//         "MBPRK04",
	//         "MBCONS01",
	//         "USDC",
	//         "WBX",
	//         "CHZ",
	//         "MBCONS02",
	//         "PAXG",
	//         "MBVASCO01",
	//         "LINK"
	//     ]
	//
	var result []any = []any{}
	var amountLimits map[string]any = SafeMapTyped(this.Options, "limits")
	var coins []any = this.ToArray(response)
	for i := 0; i < len(coins); i++ {
		var coin *string = this.SafeString(coins, i, "")
		var baseId *string = coin
		var quoteId string = "BRL"
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		if (base == nil) || (quote == nil) {
			continue
		}
		var id string = *quote + *base
		result = append(result, map[string]any{
			"id":             id,
			"symbol":         *base + "/" + *quote,
			"base":           base,
			"quote":          quote,
			"settle":         nil,
			"baseId":         baseId,
			"quoteId":        quoteId,
			"settleId":       nil,
			"type":           "spot",
			"spot":           true,
			"margin":         false,
			"swap":           false,
			"future":         false,
			"option":         false,
			"active":         nil,
			"contract":       false,
			"linear":         nil,
			"inverse":        nil,
			"contractSize":   nil,
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision": map[string]any{
				"amount": this.ParseNumber("1e-8"),
				"price":  this.ParseNumber("1e-5"),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": this.SafeNumber(amountLimits, baseId),
					"max": nil,
				},
				"price": map[string]any{
					"min": this.ParseNumber("1e-5"),
					"max": nil,
				},
				"cost": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
			"created": nil,
			"info":    coin,
		})
	}

	ch <- AsyncResult[[]MarketInterface]{Value: MarketInterfacesFromList(result)}
	return nil
}

